'use client'

import { useEffect, useMemo, useState } from 'react'
import useSWR from 'swr'
import {
  Activity, AlertTriangle, Ban, Bell, CheckCircle2, ChevronRight, Clock3, Database, FileSearch,
  FileText, Fingerprint, Gamepad2, Gauge, Globe2, History, KeyRound, LockKeyhole, Network,
  Plus, RefreshCw, Search, Server, Settings2, Shield, ShieldAlert, ShieldCheck, SlidersHorizontal,
  Trash2, UserRoundCheck, Users, Wrench, XCircle, Zap
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { useActionConfirm } from '@/components/action-confirm-dialog'
import { ServerSecurityAccessTab } from '@/components/server-security-access-tab'

type ModuleStatus='active'|'off'|'integration-required'|'error'|'unknown'
type ModuleRow={key:string;label:string;description:string;status:ModuleStatus;enabled:boolean;toggleable:boolean;detail?:string}
type Finding={id?:string;severity:'critical'|'high'|'medium'|'low'|'info';source:string;title:string;message:string;fixId?:string|null;status?:string}
type SecurityEvent={id:number;createdAt:string;severity:string;source:string;event:string;status:string;ip?:string|null;player?:string|null;actorName?:string|null}
type IpRule={id:string;ruleType:'allow'|'deny';cidr:string;description:string;source:string;expiresAt?:string|null;createdAt:string}
type AntiCheat={available:boolean;provider?:string|null;version?:string|null;configurable:boolean;enabled:boolean;runtimeVerified?:boolean;profile:'low'|'balanced'|'strict'|'custom';falsePositiveThreshold:number;violationLevel:number;action:'log'|'warn'|'kick'|'tempban'|'ban';checks:Record<string,boolean>;supportedChecks?:string[];detail?:string;integrationStatus?:string}
type XrayProtection={supported:boolean;loader?:string;provider?:string|null;configured?:boolean;enabled:boolean;profile?:'off'|'performance'|'balanced'|'strict'|'custom';engineMode?:number;maxBlockHeight?:number;updateRadius?:number;hideAir?:boolean;usePermission?:boolean;netherConfigured?:boolean;netherEnabled?:boolean;endConfigured?:boolean;sensitivity?:'low'|'normal'|'high';minSampleMinutes?:number;requiresRestart?:boolean;detail?:string}
type XrayPlayer={uuid:string;name:string;rareDelta:number;tunnelDelta:number;diamondsDelta:number;debrisDelta:number;emeraldDelta:number;rareRatio:number;per1000:number;severity:'normal'|'low'|'medium'|'high'}
type XrayAnalytics={available:boolean;baselineReady:boolean;previousCapturedAt?:string|null;capturedAt?:string;flagged?:number;high?:number;detail?:string;players:XrayPlayer[]}
type Snapshot={scannedAt?:string;firewall?:{status:string;provider?:string;detail?:string};ports?:Array<{port:number;bind:string;service:string;expected:boolean;public:boolean}>;unexpectedPublicPorts?:number[];properties?:Record<string,unknown>;sftp?:Record<string,unknown>;fileSecurity?:Record<string,unknown>;addons?:Array<Record<string,unknown>>;backups?:Record<string,unknown>;disk?:Record<string,unknown>;antiCheat?:Record<string,unknown>;findings?:Finding[]}
type ScoreBreakdown={key:string;label:string;status:'good'|'warn'|'bad'|'unknown';penalty:number;detail:string}
type SessionRow={id:string;ipAddress:string|null;userAgent:string|null;expiresAt:string}
type AuditRow={id:number;action:string;details:Record<string,unknown>;createdAt:string}
type QuarantineRow={token:string;stored:string;originalPath:string;reason:string;sha256:string;createdAt:string;size:number}
type StatusValue={status:'active'|'off'|'integration-required'|'error'|string}
type AutomationRow={id:string;taskType:string;cadence:string;timeOfDay?:string|null;intervalMinutes?:number|null;timezoneOffsetMinutes:number;enabled:boolean;lastRunAt?:string|null;nextRunAt:string}
type SecurityData={
  summary:{score:number|null;scoreBreakdown:ScoreBreakdown[];activeThreats:number;blockedIps:number;lastScanAt:string|null;openWarnings:number};
  modules:ModuleRow[]; snapshot:Snapshot|null; findings:Finding[]; events:SecurityEvent[]; ipRules:IpRule[];
  antiCheat:AntiCheat; xrayProtection:XrayProtection|null; xrayAnalytics:XrayAnalytics|null; capabilities:string[]; policies:{active:string|null;profiles:string[]};
  notifications:{panel:StatusValue;discord:StatusValue;email:StatusValue}; history:Array<{day:string;failed:number;blocked:number;anticheat:number;files:number}>;
  historyWindows:{d1:number;d7:number;d30:number}; audit:AuditRow[]; quarantine:QuarantineRow[];
  automation:{securityScan:AutomationRow|null;fileIntegrity:AutomationRow|null;portScan:AutomationRow|null};
  access:{sessions:number;sessionDetails:SessionRow[];failedLoginAt:string|null;apiKeys:number|null;passwordChangedAt:string|null;twoFactor:'active'|'off'|'challenge-required'|'integration-required';mfa?:{currentLevel:string|null;nextLevel:string|null;verifiedFactors:number;factors:Array<{id:string;type:string;friendlyName:string}>}|null};
}

const fetcher=(url:string)=>fetch(url,{cache:'no-store'}).then(async r=>{const text=await r.text();let data:any={};try{data=text?JSON.parse(text):{}}catch{}if(!r.ok)throw new Error(data.error||`İstek başarısız (${r.status})`);return data})
const tabDefs=[['general','Genel',ShieldCheck],['network','Ağ güvenliği',Globe2],['anticheat','Hile koruması',Gamepad2],['access','Erişim',Users],['files','Dosya güvenliği',FileSearch],['events','Olaylar',Clock3],['policies','Politikalar',SlidersHorizontal],['history','Geçmiş',History]] as const
type Tab=(typeof tabDefs)[number][0]
const checkLabels:Record<string,string>={speed:'Speed',fly:'Fly',reach:'Reach',killaura:'KillAura',aimassist:'Aim Assist',autoclicker:'AutoClicker',fastplace:'FastPlace',fastbreak:'FastBreak',nofall:'NoFall',jesus:'Jesus / su üstünde yürüme',step:'Step',timer:'Timer',xray:'X-Ray davranış analizi',inventorymove:'Inventory Move',scaffold:'Scaffold',blink:'Blink',phase:'Phase',noslow:'NoSlow',velocity:'Velocity / Knockback',criticals:'Criticals',rotations:'Impossible Rotations',packet:'Paket manipülasyonu',invalidmovement:'Invalid Movement',teleport:'Teleport abuse',elytra:'Elytra exploit',boatfly:'Boat / Fly exploit',fastbow:'FastBow',fastheal:'FastHeal',fastuse:'FastUse',noswing:'NoSwing',sprint:'Illegal Sprint',sneak:'Illegal Sneak',badpackets:'BadPackets',nuker:'Nuker',ghosthand:'GhostHand',blockreach:'Block Reach',entityreach:'Entity Reach',inventoryclick:'Inventory Click / Macro',groundspoof:'Ground Spoof',timerbalance:'Timer Balance',crashclient:'Crash / Malformed Packet'}
const policyLabels:Record<string,string>={standard:'Standart',strict:'Sıkı',public:'Public SMP',private:'Private SMP',cracked:'Cracked sunucu',custom:'Gelişmiş / Özel'}

export function ServerSecurityCenter({serverId,running,onNavigate}:{serverId:string;running:boolean;onNavigate?:(section:string)=>void}){
  const {data,error,mutate,isLoading}=useSWR<SecurityData>(`/api/security?serverId=${serverId}`,fetcher,{refreshInterval:10000})
  const [tab,setTab]=useState<Tab>('general'); const [busy,setBusy]=useState(''); const [notice,setNotice]=useState(''); const [eventQuery,setEventQuery]=useState('')
  const caps=new Set(data?.capabilities??[])
  async function act(action:string,payload:Record<string,unknown>={}){setBusy(action);setNotice('');try{const r=await fetch('/api/security',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({serverId,action,...payload})});const text=await r.text();let d:any={};try{d=text?JSON.parse(text):{}}catch{}if(!r.ok)throw new Error(d.error||`İşlem başarısız (${r.status})`);setNotice(d.message||'İşlem tamamlandı.');await mutate();return d}catch(e){setNotice(e instanceof Error?e.message:'İşlem başarısız');return null}finally{setBusy('')}}
  const filteredEvents=useMemo(()=>{const q=eventQuery.trim().toLocaleLowerCase('tr-TR');return (data?.events??[]).filter(e=>!q||[e.severity,e.source,e.event,e.status,e.ip,e.player,e.actorName].join(' ').toLocaleLowerCase('tr-TR').includes(q))},[data?.events,eventQuery])
  const openTab=(next:Tab)=>setTab(next)
  if(error)return <Notice tone="danger" title="Güvenlik verileri alınamadı" text={error.message}/>
  if(isLoading||!data)return <div className="rounded-xl border border-emerald-950/70 bg-[#0b1914] p-8 text-sm text-slate-400"><RefreshCw className="mr-2 inline size-4 animate-spin"/>Güvenlik verileri yükleniyor…</div>
  const scanFresh=data.summary.lastScanAt?Date.now()-new Date(data.summary.lastScanAt).getTime()<15*60*1000:false
  return <div className="space-y-3">
    {notice&&<div role="status" className="rounded-lg border border-emerald-500/25 bg-emerald-950/30 px-4 py-2.5 text-xs text-emerald-200">{notice}</div>}
    <div className="grid grid-cols-2 gap-2 md:grid-cols-4 xl:grid-cols-8">{tabDefs.map(([key,label,Icon])=><button key={key} onClick={()=>setTab(key)} className={`flex min-h-10 items-center justify-center gap-2 rounded-lg border px-2 text-xs font-semibold transition ${tab===key?'border-emerald-400/60 bg-emerald-500/10 text-emerald-300':'border-emerald-950/70 bg-[#081712] text-slate-400 hover:text-white'}`}><Icon className="size-3.5"/>{label}</button>)}</div>

    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
      <SummaryCard icon={Shield} title="Genel güvenlik puanı" value={data.summary.score===null?'Taranmadı':`${data.summary.score} / 100`} detail={data.summary.score===null?'İlk gerçek taramayı başlatın.':'Gerçek kontrollerden hesaplanır.'} onClick={()=>openTab('general')} tone={data.summary.score===null?'warn':data.summary.score<75?'warn':'good'}/>
      <SummaryCard icon={ShieldAlert} title="Aktif tehditler" value={String(data.summary.activeThreats)} detail="Kritik / yüksek açık bulgular" onClick={()=>openTab('events')} tone={data.summary.activeThreats?'danger':'good'}/>
      <SummaryCard icon={Ban} title="Engellenen IP" value={String(data.summary.blockedIps)} detail="Gerçek deny kuralları" onClick={()=>openTab('network')} tone="good"/>
      <SummaryCard icon={Search} title="Son güvenlik taraması" value={data.summary.lastScanAt?timeAgo(data.summary.lastScanAt):'Henüz yok'} detail={scanFresh?'Sonuç güncel':'Tarama yenilenebilir'} onClick={()=>void act('scan')} tone={scanFresh?'good':'warn'}/>
      <SummaryCard icon={Bell} title="Açık güvenlik uyarıları" value={String(data.summary.openWarnings)} detail="İncelenmesi gereken bulgular" onClick={()=>openTab('events')} tone={data.summary.openWarnings?'warn':'good'}/>
    </div>

    {tab==='general'&&<>
      <div className="grid gap-3 xl:grid-cols-[1.02fr_.95fr_.92fr]">
        <Card title="Koruma modülleri" subtitle="Yalnız agent gerçekten uygulayabiliyorsa anahtar açılır." icon={Settings2}>
          <div className="space-y-1">{data.modules.map(m=><Module key={m.key} row={m} busy={busy===`module:${m.key}`} onToggle={enabled=>void act('set-module',{key:m.key,enabled})}/>)}</div>
        </Card>
        <div className="space-y-3">
          <AntiCheatCard antiCheat={data.antiCheat} busy={busy} running={running} onAction={act} onNavigate={onNavigate}/>
          <NetworkRulesCard data={data} onTab={()=>openTab('network')}/>
        </div>
        <div className="space-y-3">
          <Card title="Güvenlik durumu" subtitle="Son agent taramasının gerçek bileşen sonuçları." icon={Activity}>
            <Health label="Ağ koruması" value={healthFrom(data.snapshot?.firewall?.status==='active',data.summary.lastScanAt)}/>
            <Health label="Kimlik doğrulama" value={healthFrom(Boolean(data.snapshot?.properties?.onlineMode),data.summary.lastScanAt)}/>
            <Health label="SFTP" value={healthFrom(Boolean((data.snapshot?.sftp as any)?.ready),data.summary.lastScanAt)}/>
            <Health label="Dosya güvenliği" value={healthFrom(!data.findings.some(f=>f.source==='files'&&['critical','high'].includes(f.severity)),data.summary.lastScanAt)}/>
            <Health label="Hile koruması" value={data.antiCheat.available?(data.antiCheat.enabled?100:45):null}/>
            <Health label="Yedek bütünlüğü" value={healthFrom(Boolean((data.snapshot?.backups as any)?.recent),data.summary.lastScanAt)}/>
          </Card>
          <Warnings findings={data.findings.slice(0,6)} onFix={f=>f.fixId&&void act('fix-finding',{fixId:f.fixId})} onAll={()=>openTab('events')}/>
          <QuickActions busy={busy} onAction={act} onNavigate={onNavigate} onTab={openTab}/>
        </div>
      </div>
      <div className="grid gap-3 xl:grid-cols-[1.12fr_.88fr]">
        <EventsTable events={filteredEvents.slice(0,8)} query={eventQuery} setQuery={setEventQuery} onAll={()=>openTab('events')}/>
        <IpLists rules={data.ipRules} compact onAdd={(ruleType)=>addIpRule(ruleType,act)} onRemove={id=>void act('ip-remove',{id})}/>
      </div>
      <div className="grid gap-3 xl:grid-cols-3">
        <ScoreBreakdownCard items={data.summary.scoreBreakdown}/>
        <Card title="Bildirim kanalları" subtitle="Çalışmayan kanal aktif gösterilmez." icon={Bell}>
          <IntegrationRow label="Panel içi güvenlik olayları" status={data.notifications.panel.status}/>
          <IntegrationRow label="Discord webhook" status={data.notifications.discord.status}/>
          <IntegrationRow label="E-posta uyarıları" status={data.notifications.email.status}/>
          <p className="mt-2 text-xs leading-4 text-slate-500">Discord ve e-posta göndericisi bağlanmadıkça test düğmesi gösterilmez.</p>
        </Card>
        <Card title="Otomatik koruma ve audit" subtitle="Zamanlama ve son yönetici değişiklikleri." icon={History}>
          <AutomationLine label="Periyodik güvenlik taraması" row={data.automation.securityScan} busy={busy} onToggle={enabled=>void act('automation-set',{kind:'security-scan',enabled,cadence:'daily',timeOfDay:'04:30',timezoneOffsetMinutes:new Date().getTimezoneOffset()})}/>
          <AutomationLine label="Periyodik dosya bütünlüğü" row={data.automation.fileIntegrity} busy={busy} onToggle={enabled=>void act('automation-set',{kind:'file-integrity',enabled,cadence:'daily',timeOfDay:'04:00',timezoneOffsetMinutes:new Date().getTimezoneOffset()})}/>
          <AutomationLine label="Periyodik port taraması" row={data.automation.portScan} busy={busy} onToggle={enabled=>void act('automation-set',{kind:'port-scan',enabled,cadence:'interval',intervalMinutes:360,timezoneOffsetMinutes:new Date().getTimezoneOffset()})}/>
          <div className="mt-2 border-t border-emerald-950/50 pt-2">{data.audit.slice(0,4).map(a=><div key={a.id} className="flex items-center justify-between gap-2 py-1 text-xs"><span className="truncate text-slate-300">{a.action}</span><span className="shrink-0 text-slate-600">{timeAgo(a.createdAt)}</span></div>)}{!data.audit.length&&<p className="text-xs text-slate-600">Henüz güvenlik audit kaydı yok.</p>}</div>
        </Card>
      </div>
    </>}

    {tab==='network'&&<NetworkTab data={data} busy={busy} act={act}/>} 
    {tab==='anticheat'&&<AntiCheatTab antiCheat={data.antiCheat} xrayProtection={data.xrayProtection} xrayAnalytics={data.xrayAnalytics} running={running} busy={busy} act={act} onNavigate={onNavigate}/>} 
    {tab==='access'&&<ServerSecurityAccessTab data={data} busy={busy} act={act}/>} 
    {tab==='files'&&<FilesTab data={data} busy={busy} act={act} onNavigate={onNavigate}/>} 
    {tab==='events'&&<EventsFull events={filteredEvents} query={eventQuery} setQuery={setEventQuery}/>} 
    {tab==='policies'&&<PoliciesTab data={data} busy={busy} act={act}/>} 
    {tab==='history'&&<HistoryTab data={data}/>} 
  </div>
}

function Card({title,subtitle,icon:Icon,action,children}:{title:string;subtitle?:string;icon?:React.ComponentType<{className?:string}>;action?:React.ReactNode;children:React.ReactNode}){return <section className="rounded-xl border border-emerald-950/70 bg-[linear-gradient(145deg,rgba(15,33,26,.94),rgba(7,21,16,.94))] p-3.5"><div className="mb-3 flex items-start justify-between gap-3"><div className="flex gap-2.5">{Icon&&<div className="grid size-8 shrink-0 place-items-center rounded-lg bg-emerald-500/10 text-emerald-300"><Icon className="size-4"/></div>}<div><h4 className="text-[13px] font-semibold text-white">{title}</h4>{subtitle&&<p className="mt-0.5 text-xs leading-4 text-slate-500">{subtitle}</p>}</div></div>{action}</div>{children}</section>}
function SummaryCard({icon:Icon,title,value,detail,onClick,tone}:{icon:React.ComponentType<{className?:string}>;title:string;value:string;detail:string;onClick:()=>void;tone:'good'|'warn'|'danger'}){const toneClass=tone==='danger'?'text-red-300 bg-red-500/10':tone==='warn'?'text-amber-300 bg-amber-500/10':'text-emerald-300 bg-emerald-500/10';return <button onClick={onClick} className="group rounded-xl border border-emerald-950/70 bg-[#0b1c16] p-3 text-left hover:border-emerald-800"><div className="flex items-start gap-3"><div className={`grid size-10 shrink-0 place-items-center rounded-lg ${toneClass}`}><Icon className="size-5"/></div><div className="min-w-0 flex-1"><p className="text-xs text-slate-400">{title}</p><p className="mt-1 text-lg font-semibold text-white">{value}</p><p className="mt-0.5 truncate text-xs text-slate-500">{detail}</p></div><ChevronRight className="mt-1 size-3 text-slate-600 group-hover:text-emerald-300"/></div></button>}
function statusLabel(status:ModuleStatus){return status==='active'?'Aktif':status==='off'?'Kapalı':status==='integration-required'?'Entegrasyon gerekli':status==='error'?'Hata':'Bilinmiyor'}
function statusClass(status:ModuleStatus){return status==='active'?'text-emerald-300':status==='off'?'text-slate-400':status==='error'?'text-red-300':status==='integration-required'?'text-amber-300':'text-slate-500'}
function Module({row,busy,onToggle}:{row:ModuleRow;busy:boolean;onToggle:(v:boolean)=>void}){return <div className="flex items-center gap-3 rounded-lg border border-emerald-950/45 bg-black/10 px-2.5 py-2"><div className="grid size-7 shrink-0 place-items-center rounded-md bg-emerald-500/[.07] text-emerald-300"><Shield className="size-3.5"/></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-xs font-semibold text-white">{row.label}</p><span className={`text-xs ${statusClass(row.status)}`}>● {statusLabel(row.status)}</span></div><p className="truncate text-xs text-slate-500">{row.detail||row.description}</p></div><button aria-label={`${row.label} ${row.enabled?'kapat':'aç'}`} disabled={!row.toggleable||busy} onClick={()=>onToggle(!row.enabled)} className={`relative h-5 w-9 rounded-full transition ${row.enabled&&row.status==='active'?'bg-emerald-500':'bg-slate-800'} disabled:cursor-not-allowed disabled:opacity-35`}><span className={`absolute top-0.5 size-4 rounded-full bg-white transition ${row.enabled&&row.status==='active'?'left-[18px]':'left-0.5'}`}/></button></div>}
function AntiCheatCard({antiCheat,busy,running,onAction,onNavigate}:{antiCheat:AntiCheat;busy:string;running:boolean;onAction:(a:string,p?:Record<string,unknown>)=>Promise<any>;onNavigate?:(s:string)=>void}){const status=!antiCheat.available?'Entegrasyon gerekli':antiCheat.configurable?(antiCheat.enabled?(antiCheat.runtimeVerified?'Aktif · doğrulandı':'Kurulu · telemetri bekleniyor'):'Kapalı'):'Algılandı · sağlayıcıya bağlı';const statusTone=antiCheat.runtimeVerified?'bg-emerald-500/10 text-emerald-300':antiCheat.available?'bg-blue-500/10 text-blue-300':'bg-amber-500/10 text-amber-300';return <Card title="Gelişmiş hile koruması" subtitle={antiCheat.available?`${antiCheat.provider}${antiCheat.version?` ${antiCheat.version}`:''} disk üzerinde algılandı${antiCheat.configurable?' · panel config desteği var':' · sağlayıcı config’i ayrı yönetilir'}`:'Gerçek bir anti-cheat plugin/mod algılanmadı.'} icon={Gamepad2} action={<span className={`rounded px-2 py-1 text-xs ${statusTone}`}>{status}</span>}>
    {!antiCheat.available?<div className="rounded-lg border border-amber-500/20 bg-amber-950/10 p-3"><p className="text-xs leading-4 text-amber-100">Speed, Fly, Reach, KillAura, Aim Assist, AutoClicker, FastPlace/FastBreak, NoFall, Jesus, Step, Timer, X-Ray, Inventory Move, Scaffold, Blink, Phase, NoSlow, Velocity, Criticals, rotations, packet, invalid movement, teleport, Elytra ve Boat/Fly kontrolleri gerçek sunucu içi sağlayıcıyla çalışır.</p><div className="mt-2 flex gap-2"><Button size="sm" className="h-7 bg-emerald-600 px-2 text-xs text-emerald-950" disabled={!!busy||running} onClick={()=>void onAction('anticheat-install')}><Plus className="mr-1 size-3"/>Hile koruması ekle</Button><Button size="sm" variant="outline" className="h-7 px-2 text-xs" onClick={()=>onNavigate?.('software')}><Wrench className="mr-1 size-3"/>JAR / mod yükle</Button></div></div>:<><div className="grid grid-cols-2 gap-1.5">{Object.entries(antiCheat.checks).slice(0,10).map(([k,v])=><div key={k} className="flex items-center justify-between rounded-md border border-emerald-950/45 px-2 py-1.5 text-xs"><span>{checkLabels[k]||k}</span><span className={antiCheat.configurable?(v?'text-emerald-300':'text-slate-500'):'text-blue-300'}>{antiCheat.configurable?(v?'Açık':'Kapalı'):'Sağlayıcıya bağlı'}</span></div>)}</div><Button size="sm" variant="outline" className="mt-2 h-7 w-full text-xs" onClick={()=>void onAction('anticheat-detect')}><RefreshCw className="mr-1 size-3"/>Entegrasyonu tekrar doğrula</Button></>}
  </Card>}
function NetworkRulesCard({data,onTab}:{data:SecurityData;onTab:()=>void}){const props=data.snapshot?.properties as any;return <Card title="Ağ ve erişim kuralları" subtitle="Gerçek scan sonucu ve kayıtlı IP kuralları." icon={Globe2} action={<button onClick={onTab} className="text-xs text-emerald-300">Düzenle →</button>}><Row label="IP allowlist" value={`${data.ipRules.filter(x=>x.ruleType==='allow').length} kayıt`}/><Row label="Yasaklı IP listesi" value={`${data.ipRules.filter(x=>x.ruleType==='deny').length} kayıt`}/><Row label="Beklenmeyen açık port" value={`${data.snapshot?.unexpectedPublicPorts?.length??0}`}/><Row label="RCON" value={props?.rconEnabled?'Açık':'Kapalı'}/><Row label="Query" value={props?.queryEnabled?'Açık':'Kapalı'}/><Row label="SFTP" value={(data.snapshot?.sftp as any)?.ready?'Doğrulandı':'Doğrulanmadı'}/></Card>}
function Row({label,value}:{label:string;value:string}){return <div className="flex items-center justify-between border-b border-emerald-950/40 py-1.5 text-xs last:border-0"><span className="text-slate-300">{label}</span><span className="font-medium text-emerald-300">{value}</span></div>}
function Health({label,value}:{label:string;value:number|null}){return <div className="grid grid-cols-[110px_1fr_36px] items-center gap-2 py-1.5 text-xs"><span>{label}</span><div className="h-1.5 rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{width:`${value??0}%`}}/></div><span className="text-right text-slate-400">{value===null?'—':`${value}%`}</span></div>}
function healthFrom(ok:boolean,last:string|null){return last?ok?100:45:null}
function Warnings({findings,onFix,onAll}:{findings:Finding[];onFix:(f:Finding)=>void;onAll:()=>void}){return <Card title="Uyarılar ve öneriler" subtitle="Gerçek yapılandırmadan üretilen bulgular." icon={AlertTriangle} action={<button onClick={onAll} className="text-xs text-emerald-300">Tümü →</button>}>{findings.length?findings.map((f,i)=><div key={f.id||i} className="flex items-start gap-2 border-b border-emerald-950/40 py-2 last:border-0"><SeverityDot severity={f.severity}/><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-white">{f.title}</p><p className="mt-0.5 line-clamp-2 text-xs leading-4 text-slate-500">{f.message}</p></div>{f.fixId&&<button onClick={()=>onFix(f)} className="rounded border border-emerald-900 px-2 py-1 text-xs text-emerald-300">Düzelt</button>}</div>):<p className="py-5 text-center text-xs text-slate-500">Açık bulgu yok veya henüz tarama yapılmadı.</p>}</Card>}
function SeverityDot({severity}:{severity:string}){const c=severity==='critical'||severity==='high'?'bg-red-400':severity==='medium'?'bg-amber-400':severity==='low'?'bg-blue-400':'bg-slate-400';return <span className={`mt-1.5 size-2 shrink-0 rounded-full ${c}`}/>} 
function QuickActions({busy,onAction,onNavigate,onTab}:{busy:string;onAction:(a:string,p?:Record<string,unknown>)=>Promise<any>;onNavigate?:(s:string)=>void;onTab:(t:Tab)=>void}){const items=[['scan','Güvenlik taraması başlat',Search],['port-scan','Açık portları tara',Network],['file-integrity','Dosya bütünlüğünü kontrol et',Fingerprint],['sftp-verify','SFTP doğrula',KeyRound],['terminate-sessions','Tüm SFTP oturumlarını sonlandır',Users],['policy-open','Güvenlik politikasını uygula',ShieldCheck]] as const;return <Card title="Hızlı işlemler" subtitle="Yalnız gerçek işlemlere bağlı düğmeler." icon={Zap}><div className="grid grid-cols-2 gap-1.5">{items.map(([key,label,Icon])=><button key={key} disabled={!!busy&&key!=='policy-open'} onClick={()=>key==='policy-open'?onTab('policies'):void onAction(key)} className="flex min-h-8 items-center gap-1.5 rounded-md border border-emerald-950/60 bg-black/10 px-2 text-left text-xs hover:bg-emerald-950/25 disabled:opacity-40"><Icon className="size-3.5"/>{label}</button>)}<button onClick={()=>onNavigate?.('logs')} className="flex min-h-8 items-center gap-1.5 rounded-md border border-emerald-950/60 bg-black/10 px-2 text-xs"><FileText className="size-3.5"/>Günlüğe git</button><button onClick={()=>onTab('network')} className="flex min-h-8 items-center gap-1.5 rounded-md border border-emerald-950/60 bg-black/10 px-2 text-xs"><Ban className="size-3.5"/>IP engelle</button><button onClick={()=>onTab('files')} className="flex min-h-8 items-center gap-1.5 rounded-md border border-emerald-950/60 bg-black/10 px-2 text-xs"><ShieldAlert className="size-3.5"/>Karantinayı aç</button></div></Card>}
function EventsTable({events,query,setQuery,onAll}:{events:SecurityEvent[];query:string;setQuery:(v:string)=>void;onAll:()=>void}){return <Card title="Son güvenlik olayları" subtitle="Tarama, ağ, SFTP, anti-cheat ve yönetici işlemleri." icon={Clock3} action={<button onClick={onAll} className="text-xs text-emerald-300">Tüm olayları görüntüle →</button>}><div className="mb-2 relative"><Search className="absolute left-2.5 top-2 size-3.5 text-slate-600"/><Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Olay, IP, oyuncu veya yönetici ara…" className="h-8 border-emerald-950/70 bg-black/10 pl-8 text-xs"/></div><div className="overflow-x-auto"><table className="w-full min-w-[920px] text-xs"><thead className="text-left text-slate-500"><tr><th className="pb-2">Zaman</th><th>Seviye</th><th>Kaynak</th><th>Olay</th><th>Durum</th><th>IP</th><th>Oyuncu</th><th>Yönetici</th></tr></thead><tbody>{events.map(e=><tr key={e.id} className="border-t border-emerald-950/45"><td className="py-1.5 text-slate-500">{new Date(e.createdAt).toLocaleString('tr-TR')}</td><td><Badge text={e.severity}/></td><td>{e.source}</td><td className="max-w-[260px] truncate text-slate-300">{e.event}</td><td>{e.status}</td><td className="font-mono text-slate-400">{e.ip||'—'}</td><td>{e.player||'—'}</td><td>{e.actorName||'—'}</td></tr>)}</tbody></table>{!events.length&&<p className="py-5 text-center text-xs text-slate-500">Kayıt yok.</p>}</div></Card>}
function Badge({text}:{text:string}){const l=text.toLowerCase();const c=l.includes('critical')||l.includes('kritik')||l.includes('high')||l.includes('yüksek')?'bg-red-500/10 text-red-300':l.includes('medium')||l.includes('orta')?'bg-amber-500/10 text-amber-300':l.includes('low')||l.includes('düşük')?'bg-blue-500/10 text-blue-300':'bg-slate-800 text-slate-300';return <span className={`rounded px-1.5 py-0.5 ${c}`}>{text}</span>}
function IpLists({rules,compact=false,onAdd,onRemove}:{rules:IpRule[];compact?:boolean;onAdd:(t:'allow'|'deny')=>void;onRemove:(id:string)=>void}){return <Card title="IP yönetimi" subtitle="IP/CIDR izin ve engel kuralları; süre bitince node helper kuralı otomatik temizler." icon={Users}><div className="grid gap-3 sm:grid-cols-2">{(['allow','deny'] as const).map(type=><div key={type} className="rounded-lg border border-emerald-950/50 bg-black/10 p-2.5"><div className="mb-2 flex items-center justify-between"><b className="text-xs">{type==='allow'?'IP izin kuralları':'Engellenen IP’ler'} ({rules.filter(x=>x.ruleType===type).length})</b><button onClick={()=>onAdd(type)} className={`rounded px-2 py-1 text-xs ${type==='allow'?'bg-emerald-500 text-emerald-950':'border border-red-500/40 text-red-300'}`}><Plus className="mr-1 inline size-3"/>Ekle</button></div>{rules.filter(x=>x.ruleType===type).slice(0,compact?5:30).map(r=><div key={r.id} className="flex items-center gap-2 border-t border-emerald-950/40 py-1.5 text-xs"><div className="min-w-0 flex-1"><div className="font-mono text-slate-200">{r.cidr}</div><div className="truncate text-slate-500">{r.description||'Açıklama yok'} · {r.source==='manual'?'Manuel':r.source}{r.expiresAt?` · ${timeAgo(r.expiresAt)} sona erer`:' · Kalıcı'}</div></div><button onClick={()=>onRemove(r.id)} className="text-red-400" title="Kuralı kaldır"><Trash2 className="size-3"/></button></div>)}{!rules.some(x=>x.ruleType===type)&&<p className="py-4 text-center text-xs text-slate-600">Kayıt yok</p>}</div>)}</div><p className="mt-2 text-xs leading-4 text-slate-600">Not: “izin kuralı” tek başına sunucuyu yalnız bu IP’lere kapatmaz. Tam allowlist kilidi ayrı bir deny-all politikası gerektirir ve yanlış yapılandırılırsa erişimi kesebilir.</p></Card>}
async function addIpRule(ruleType:'allow'|'deny',act:(a:string,p?:Record<string,unknown>)=>Promise<any>){const cidr=prompt(ruleType==='allow'?'İzin verilecek IP/CIDR:':'Engellenecek IP/CIDR:');if(!cidr)return;const description=prompt('Açıklama (isteğe bağlı):')||'';const duration=prompt('Süre: 1h, 24h, 7d veya permanent','24h')||'24h';await act('ip-add',{ruleType,cidr,description,duration})}

function NetworkTab({data,busy,act}:{data:SecurityData;busy:string;act:(a:string,p?:Record<string,unknown>)=>Promise<any>}){return <div className="grid gap-3 xl:grid-cols-[1fr_.9fr]"><div className="space-y-3"><Card title="Açık portlar" subtitle="Agent, işletim sistemindeki dinleyen TCP portlarını gerçek zamanlı tarar." icon={Network} action={<Button size="sm" className="h-7 bg-emerald-600 px-2 text-xs text-emerald-950" disabled={!!busy} onClick={()=>void act('port-scan')}><Search className="mr-1 size-3"/>Tara</Button>}><div className="overflow-x-auto"><table className="w-full text-xs"><thead className="text-left text-slate-500"><tr><th className="pb-2">Port</th><th>Bind</th><th>Servis</th><th>Beklenen</th><th>Dış erişim</th></tr></thead><tbody>{(data.snapshot?.ports??[]).map(p=><tr key={`${p.bind}:${p.port}`} className="border-t border-emerald-950/45"><td className="py-2 font-mono">{p.port}</td><td>{p.bind}</td><td>{p.service}</td><td className={p.expected?'text-emerald-300':'text-amber-300'}>{p.expected?'Evet':'Hayır'}</td><td>{p.public?'Açık':'Yerel'}</td></tr>)}</tbody></table>{!data.snapshot?.ports?.length&&<p className="py-6 text-center text-xs text-slate-500">Henüz port taraması yapılmadı.</p>}</div></Card><IpLists rules={data.ipRules} onAdd={t=>addIpRule(t,act)} onRemove={id=>void act('ip-remove',{id})}/></div><div className="space-y-3"><Card title="Firewall ve bağlantı koruması" subtitle="Her özellik yalnız gerçekten desteklenen capability ile gösterilir." icon={Shield}><Row label="Firewall" value={data.snapshot?.firewall?.status||'Bilinmiyor'}/><Row label="Sağlayıcı" value={data.snapshot?.firewall?.provider||'—'}/><Row label="Beklenmeyen public port" value={String(data.snapshot?.unexpectedPublicPorts?.length??0)}/><Row label="TCP connection rate-limit" value={capsText(data,'connection-rate-limit')}/><Row label="IP/CIDR firewall kuralları" value={capsText(data,'ip-cidr')}/><Row label="Minecraft login brute-force" value="Entegrasyon gerekli"/><Row label="Packet flood / PPS limiti" value="Entegrasyon gerekli"/></Card><Notice tone="info" title="Oracle Cloud katmanı ayrı çalışır" text="Oracle Cloud Security List / NSG ile Ubuntu üzerindeki UFW/nftables aynı şey değildir. Panel node içindeki firewall durumunu doğrular; OCI ağ kuralının dış erişimi ayrıca yönetilmelidir."/></div></div>}
function capsText(data:SecurityData,cap:string){return data.capabilities.includes(cap)?'Destekleniyor':'Entegrasyon gerekli'}
function AntiCheatTab({antiCheat,xrayProtection,xrayAnalytics,running,busy,act,onNavigate}:{antiCheat:AntiCheat;xrayProtection:XrayProtection|null;xrayAnalytics:XrayAnalytics|null;running:boolean;busy:string;act:(a:string,p?:Record<string,unknown>)=>Promise<any>;onNavigate?:(s:string)=>void}){
  const editable=antiCheat.available&&antiCheat.configurable&&!running
  const save=(patch:Record<string,unknown>)=>act('anticheat-config',{config:{...antiCheat,...patch}})
  const runtime=antiCheat.runtimeVerified?'Doğrulandı':antiCheat.available?'Doğrulanmadı':'Yok'
  return <div className="space-y-3">
    <div className="grid gap-3 xl:grid-cols-[.72fr_1.28fr]">
      <div className="space-y-3">
        <Card title="Anti-cheat entegrasyonu" subtitle="Dosyanın varlığı ile gerçek çalışma telemetrisi birbirinden ayrılır." icon={Gamepad2}>
          <Row label="Sağlayıcı" value={antiCheat.provider||'Algılanmadı'}/>
          <Row label="Sürüm" value={antiCheat.version||'Bilinmiyor'}/>
          <Row label="Dosya durumu" value={antiCheat.available?(antiCheat.enabled?'Etkin dosya':'Devre dışı'):'Entegrasyon gerekli'}/>
          <Row label="Çalışma telemetrisi" value={runtime}/>
          <Row label="Panelden yapılandırma" value={antiCheat.configurable?'Destekleniyor':'Sağlayıcıya bağlı'}/>
          <Row label="Kontrol sayısı" value={`${Object.keys(checkLabels).length} hile sınıfı`}/>
          <div className="mt-3 flex flex-wrap gap-2">
            <Button size="sm" className="h-8 bg-emerald-600 text-xs text-emerald-950" disabled={!!busy||running} onClick={()=>void act('anticheat-install')}><Plus className="mr-1 size-3"/>Hile koruması ekle</Button>
            <Button size="sm" variant="outline" className="h-8 text-xs" disabled={!antiCheat.available||!antiCheat.configurable||!!busy||running} onClick={()=>void act('set-module',{key:'anticheat',enabled:!antiCheat.enabled})}>{antiCheat.enabled?'Hile korumasını kapat':'Hile korumasını aç'}</Button>
            <Button size="sm" variant="outline" className="h-8 text-xs" onClick={()=>void act('anticheat-detect')}><RefreshCw className="mr-1 size-3"/>Tekrar algıla</Button>
            <Button size="sm" variant="outline" className="h-8 text-xs" onClick={()=>onNavigate?.('software')}><Wrench className="mr-1 size-3"/>Yazılıma git</Button>
          </div>
          {running&&<p className="mt-3 text-xs text-amber-300">Anti-cheat dosyası/config değişiklikleri için sunucuyu durdurun. Canlı telemetri ve madencilik analizi sunucu açıkken de okunabilir.</p>}
        </Card>
        <Notice tone="info" title="Sağlayıcı gerçeği" text="GrimAC, Vulcan, Matrix, Spartan, NCP, Themis ve Negativity algılanabilir; fakat sürüme özel güvenli config eşlemesi yoksa panel onları değiştirmez. BlockCtrl uyumlu sağlayıcı telemetri üretirse gerçek çalışma durumu doğrulanır."/>
      </div>
      <Card title="Gelişmiş hile kontrolleri" subtitle={`${Object.keys(checkLabels).length} kontrol anahtarı; yalnız BlockCtrl uyumlu sağlayıcıda doğrudan uygulanır.`} icon={ShieldAlert}>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {Object.entries(checkLabels).map(([key,label])=><label key={key} className={`flex items-center justify-between rounded-lg border border-emerald-950/50 p-2.5 text-xs ${!editable?'opacity-55':''}`}>
            <span><b>{label}</b><span className="mt-0.5 block text-xs text-slate-500">{editable?'Ayrı kontrol':'Sağlayıcı/entegrasyon gerekli'}</span></span>
            <input type="checkbox" checked={Boolean(antiCheat.checks[key])} disabled={!editable||!!busy} onChange={e=>void save({checks:{...antiCheat.checks,[key]:e.target.checked}})} className="size-4 accent-emerald-500"/>
          </label>)}
        </div>
        <div className="mt-3 grid gap-2 md:grid-cols-4">
          <Select label="Profil" value={antiCheat.profile} disabled={!editable} options={[['low','Düşük'],['balanced','Dengeli'],['strict','Katı'],['custom','Özel']]} onChange={v=>void save({profile:v})}/>
          <NumberField label="False positive eşiği" value={antiCheat.falsePositiveThreshold} disabled={!editable} onChange={v=>void save({falsePositiveThreshold:v})}/>
          <NumberField label="Violation level" value={antiCheat.violationLevel} disabled={!editable} onChange={v=>void save({violationLevel:v})}/>
          <Select label="İhlalde eylem" value={antiCheat.action} disabled={!editable} options={[['log','Sadece logla'],['warn','Uyar'],['kick','Kick'],['tempban','Geçici ban'],['ban','Kalıcı ban']]} onChange={v=>void save({action:v})}/>
        </div>
        <Notice tone="info" title="Otomatik ceza yalnız doğrulanmış sağlayıcıda" text="Panel hız, combat, hareket ve paket kontrollerini yapılandırır. Gerçek tespit algoritması sunucu içinde çalışan sağlayıcıdadır. X-Ray için ayrıca aşağıdaki sunucu-tarafı obfuscation ve istatistik analizi kullanılır."/>
      </Card>
    </div>
    <XrayProtectionCard protection={xrayProtection} analytics={xrayAnalytics} running={running} busy={busy} act={act} onNavigate={onNavigate}/>
  </div>
}

function XrayProtectionCard({protection,analytics,running,busy,act,onNavigate}:{protection:XrayProtection|null;analytics:XrayAnalytics|null;running:boolean;busy:string;act:(a:string,p?:Record<string,unknown>)=>Promise<any>;onNavigate?:(s:string)=>void}){
  const actionConfirm=useActionConfirm()
  const [profile,setProfile]=useState<'performance'|'balanced'|'strict'|'custom'>('balanced')
  const [engineMode,setEngineMode]=useState(2)
  const [maxBlockHeight,setMaxBlockHeight]=useState(64)
  const [updateRadius,setUpdateRadius]=useState(2)
  const [hideAir,setHideAir]=useState(false)
  const [usePermission,setUsePermission]=useState(false)
  useEffect(()=>{if(!protection)return;const p=protection.profile;if(p&&p!=='off')setProfile(p);setEngineMode(protection.engineMode??2);setMaxBlockHeight(protection.maxBlockHeight??64);setUpdateRadius(protection.updateRadius??2);setHideAir(Boolean(protection.hideAir));setUsePermission(Boolean(protection.usePermission))},[protection?.profile,protection?.engineMode,protection?.maxBlockHeight,protection?.updateRadius,protection?.hideAir,protection?.usePermission])
  const supported=Boolean(protection?.supported)
  const apply=(enabled=true)=>act('xray-config',{config:{enabled,profile,engineMode,maxBlockHeight,updateRadius,hideAir,usePermission,analytics:true}})
  const quick=(p:'performance'|'balanced'|'strict')=>act('xray-config',{config:{enabled:true,profile:p,analytics:true}})
  const severityClass=(s:XrayPlayer['severity'])=>s==='high'?'text-red-300 bg-red-500/10':s==='medium'?'text-amber-300 bg-amber-500/10':s==='low'?'text-blue-300 bg-blue-500/10':'text-emerald-300 bg-emerald-500/10'
  return <>{actionConfirm.dialog}<div className="grid gap-3 xl:grid-cols-[.85fr_1.15fr]">
    <Card title="İleri seviye X-Ray engelleme" subtitle="Paper/Purpur'da gerçek sunucu-tarafı chunk obfuscation kullanılır. Geçerli Paper motorları Mode 1 ve Mode 2'dir; güçlü profilde Mode 2 kullanılır." icon={Fingerprint}>
      <Row label="Loader" value={protection?.loader||'Bilinmiyor'}/>
      <Row label="Koruma motoru" value={supported?(protection?.provider||'Paper Anti-Xray'):'Entegrasyon gerekli'}/>
      <Row label="Durum" value={supported?(protection?.enabled?'Aktif':'Kapalı'):'Bu loader yerleşik obfuscation desteklemiyor'}/>
      <Row label="Profil" value={protection?.profile||'—'}/>
      <Row label="Engine mode" value={supported?String(protection?.engineMode??'—'):'—'}/>
      <Row label="Maksimum Y" value={supported?String(protection?.maxBlockHeight??'—'):'—'}/>
      <Row label="Update radius" value={supported?String(protection?.updateRadius??'—'):'—'}/>
      <Row label="Havaya açık cevher gizleme" value={supported?(protection?.hideAir?'Açık':'Kapalı'):'—'}/>
      <Row label="Nether override" value={supported?(protection?.netherConfigured?(protection?.netherEnabled?'Aktif':'Kapalı'):'Dünya oluşunca uygulanır'):'—'}/>
      {supported?<div className="mt-3 space-y-3">
        <div className="grid grid-cols-3 gap-1.5">
          <Button size="sm" variant="outline" className="h-8 px-2 text-xs" disabled={running||!!busy} onClick={()=>void quick('performance')}>Performans</Button>
          <Button size="sm" variant="outline" className="h-8 px-2 text-xs" disabled={running||!!busy} onClick={()=>void quick('balanced')}>Dengeli</Button>
          <Button size="sm" className="h-8 bg-emerald-600 px-2 text-xs text-emerald-950" disabled={running||!!busy} onClick={async()=>{if(await actionConfirm.ask('Katı X-Ray profili havayı da gizleyebilir ve bazı istemcilerde FPS düşüşü oluşturabilir.',{title:'Katı X-Ray profilini uygula',confirmLabel:'Profili uygula',danger:true}))await quick('strict')}}>Katı</Button>
        </div>
        <div className="grid gap-2 sm:grid-cols-3">
          <Select label="Özel engine" value={String(engineMode)} disabled={running||!!busy} options={[['1','Mode 1 · daha hafif'],['2','Mode 2 · güçlü obfuscation']]} onChange={v=>{setProfile('custom');setEngineMode(Number(v))}}/>
          <NumberField label="Max block height" value={maxBlockHeight} disabled={running||!!busy} onChange={v=>{setProfile('custom');setMaxBlockHeight(Math.max(16,Math.min(320,Math.round(v/16)*16)))}}/>
          <NumberField label="Update radius" value={updateRadius} disabled={running||!!busy} onChange={v=>{setProfile('custom');setUpdateRadius(Math.max(1,Math.min(2,v)))}}/>
        </div>
        <div className="grid gap-1.5 sm:grid-cols-2">
          <label className="flex items-center justify-between rounded-md border border-emerald-950/50 p-2 text-xs"><span><b>Air gizleme</b><span className="block text-xs text-slate-600">Mağarada havaya açık cevherleri de zorlaştırır; FPS maliyeti olabilir.</span></span><input type="checkbox" checked={hideAir} disabled={running||!!busy} onChange={e=>{setProfile('custom');setHideAir(e.target.checked)}} className="size-4 accent-emerald-500"/></label>
          <label className="flex items-center justify-between rounded-md border border-emerald-950/50 p-2 text-xs"><span><b>Bypass permission</b><span className="block text-xs text-slate-600">Kapalı tutulursa OP/izinli oyuncular da obfuscation görür.</span></span><input type="checkbox" checked={usePermission} disabled={running||!!busy} onChange={e=>{setProfile('custom');setUsePermission(e.target.checked)}} className="size-4 accent-emerald-500"/></label>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button size="sm" className="h-8 bg-emerald-600 text-xs text-emerald-950" disabled={running||!!busy} onClick={()=>void apply(true)}>Özel ayarı uygula</Button>
          <Button size="sm" variant="destructive" className="h-8 text-xs" disabled={running||!!busy||!protection?.enabled} onClick={async()=>{if(await actionConfirm.ask('Yerleşik X-Ray obfuscation kapatılacak.',{title:'X-Ray korumasını kapat',confirmLabel:'Korumayı kapat',danger:true,requiredText:'KAPAT'}))await apply(false)}}>X-Ray korumasını kapat</Button>
        </div>
        {running&&<p className="text-xs text-amber-300">Paper Anti-Xray yapılandırma değişikliği için sunucuyu durdurun; ardından normal restart gerekir. /reload kullanılmamalıdır.</p>}
      </div>:<div className="mt-3">
        <Notice tone="warn" title="Chunk obfuscation entegrasyonu gerekli" text={`${protection?.loader||'Bu loader'} üzerinde Paper'ın yerleşik Anti-Xray motoru yok. BlockCtrl madencilik anomalilerini yine analiz eder; fakat gerçek cevher gizleme için uyumlu server-side mod/plugin gerekir.`}/>
        <Button size="sm" variant="outline" className="mt-2 h-8 text-xs" onClick={()=>onNavigate?.('software')}><Wrench className="mr-1 size-3"/>Uyumlu mod/plugin yükle</Button>
      </div>}
    </Card>
    <Card title="X-Ray davranış analizi" subtitle="Minecraft'ın gerçek oyuncu stats dosyalarında iki örnek arasındaki cevher/tünel oranı incelenir. Bu analiz tek başına ceza vermez." icon={Search}>
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
        <div className="text-xs text-slate-500">{analytics?.detail||'Henüz X-Ray istatistik analizi çalıştırılmadı.'}</div>
        <Button size="sm" variant="outline" className="h-8 text-xs" disabled={!!busy} onClick={()=>void act('xray-analyze')}><RefreshCw className="mr-1 size-3"/>Madenciliği analiz et</Button>
      </div>
      <div className="grid gap-2 sm:grid-cols-3">
        <div className="rounded-lg border border-emerald-950/50 bg-black/10 p-2"><div className="text-xs text-slate-600">Baz çizgisi</div><div className="mt-1 text-xs font-semibold">{analytics?.baselineReady?'Hazır':'İlk örnek gerekli'}</div></div>
        <div className="rounded-lg border border-emerald-950/50 bg-black/10 p-2"><div className="text-xs text-slate-600">Şüpheli oyuncu</div><div className="mt-1 text-xs font-semibold">{analytics?.flagged??0}</div></div>
        <div className="rounded-lg border border-emerald-950/50 bg-black/10 p-2"><div className="text-xs text-slate-600">Yüksek riskli örnek</div><div className="mt-1 text-xs font-semibold">{analytics?.high??0}</div></div>
      </div>
      <div className="mt-3 overflow-x-auto">
        <table className="w-full min-w-[780px] text-xs">
          <thead className="text-left text-slate-500"><tr><th className="pb-2">Oyuncu</th><th>Nadir cevher</th><th>Diamond</th><th>Ancient Debris</th><th>Tünel bloğu</th><th>Oran</th><th>1000 blokta</th><th>Değerlendirme</th></tr></thead>
          <tbody>{(analytics?.players??[]).map(row=><tr key={row.uuid} className="border-t border-emerald-950/45"><td className="py-2 font-semibold text-white">{row.name}</td><td>{row.rareDelta}</td><td>{row.diamondsDelta}</td><td>{row.debrisDelta}</td><td>{row.tunnelDelta}</td><td>%{Math.round(row.rareRatio*1000)/10}</td><td>{row.per1000}</td><td><span className={`rounded px-2 py-1 ${severityClass(row.severity)}`}>{row.severity==='high'?'Yüksek şüphe':row.severity==='medium'?'Orta şüphe':row.severity==='low'?'Düşük şüphe':'Normal'}</span></td></tr>)}</tbody>
        </table>
        {!analytics?.players?.length&&<p className="py-8 text-center text-xs text-slate-600">{analytics?.baselineReady?'Bu örnek aralığında analiz edilecek madencilik değişimi yok.':'İlk analiz baz çizgisini kaydeder; ikinci analizden sonra oyuncu bazlı oranlar görünür.'}</p>}
      </div>
      <Notice tone="info" title="False positive koruması" text="Cevher oranı analizi yalnız sinyal üretir. Otomatik ban/kick yapılmaz; yüksek oranlar mağara, Fortune/Silk Touch, özel dünya üretimi veya kısa örnek aralığı nedeniyle de oluşabilir. Aktif engelleme için obfuscation + doğrulanmış anti-cheat birlikte kullanılmalıdır."/>
    </Card>
  </div></>
}

function FilesTab({data,busy,act,onNavigate}:{data:SecurityData;busy:string;act:(a:string,p?:Record<string,unknown>)=>Promise<any>;onNavigate?:(s:string)=>void}){const actionConfirm=useActionConfirm();const fs=data.snapshot?.fileSecurity as any;const addons=(data.snapshot?.addons??[]);const malware=fs?.malware as any;return <div className="space-y-3">{actionConfirm.dialog}<div className="grid gap-3 xl:grid-cols-[.82fr_1.18fr]"><Card title="Dosya güvenliği ve yükleme politikası" icon={FileSearch} action={<Button size="sm" className="h-7 bg-emerald-600 px-2 text-xs text-emerald-950" disabled={!!busy} onClick={()=>void act('file-integrity')}><Search className="mr-1 size-3"/>Şimdi tara</Button>}><Row label="SHA-256" value={fs?.hashing?'Aktif':'Taranmadı'}/><Row label="ZIP Slip / path traversal" value={capsText(data,'archive-safety')}/><Row label="ZIP giriş / açılmış boyut limiti" value={capsText(data,'archive-safety')}/><Row label="Symlink kontrolü" value={fs?.symlinks===0?'Temiz':fs?.symlinks?`${fs.symlinks} bulgu`:'Taranmadı'}/><Row label="Dosya izinleri" value={fs?.permissions?.worldWritable===0?'Güvenli':fs?.permissions?.worldWritable?`${fs.permissions.worldWritable} world-writable`:'Taranmadı'}/><Row label="Executable engeli" value={fs?.riskyFiles===0?'Temiz':fs?.riskyFiles?`${fs.riskyFiles} riskli`:'Taranmadı'}/><Row label="Bozuk JAR tespiti" value={fs?.brokenJars===0?'Temiz':fs?.brokenJars?`${fs.brokenJars} bozuk`:'Taranmadı'}/><Row label="Uyumsuz mod/plugin" value={fs?.incompatibleAddons===0?'Temiz':fs?.incompatibleAddons?`${fs.incompatibleAddons} bulgu`:'Taranmadı'}/><Row label="Duplicate JAR" value={fs?.duplicateHashes===0?'Temiz':fs?.duplicateHashes?`${fs.duplicateHashes} duplicate`:'Taranmadı'}/><Row label="Malware motoru" value={fs?.malwareEngine||'Entegrasyon gerekli'}/><Row label="Son malware sonucu" value={!malware?'Taranmadı':malware.status==='clean'?'Temiz':malware.status==='infected'?`${malware.infectedFiles?.length||0} bulgu`:malware.status}/></Card><Card title="Mod / Plugin bütünlüğü" subtitle="Panel dışından eklenmiş eski JAR'lar da diskten taranır; metadata ve loader hedefi kontrol edilir." icon={Database} action={<button onClick={()=>onNavigate?.('software')} className="text-xs text-emerald-300">Yazılıma git →</button>}><div className="overflow-x-auto"><table className="w-full min-w-[920px] text-xs"><thead className="text-left text-slate-500"><tr><th className="pb-2">Dosya</th><th>Tür</th><th>Sürüm</th><th>Loader</th><th>SHA-256</th><th>Değişiklik</th><th>Uyumluluk</th></tr></thead><tbody>{addons.slice(0,40).map((a:any,i)=><tr key={`${a.path}-${i}`} className="border-t border-emerald-950/40"><td className="py-2 max-w-[220px] truncate">{a.name||a.path}</td><td>{a.jarType||a.category}</td><td>{a.version||'—'}</td><td>{a.serverLoader||'—'}</td><td className="font-mono text-slate-500">{a.sha256?String(a.sha256).slice(0,12)+'…':'—'}</td><td>{a.changed?'Değişti':'—'}</td><td className={a.ok===false||a.compatibility==='incompatible'?'text-red-300':a.compatibility==='compatible'?'text-emerald-300':'text-amber-300'} title={a.compatibilityReason||''}>{a.ok===false?'Bozuk':a.compatibility==='compatible'?'Uyumlu':a.compatibility==='incompatible'?'Uyumsuz':'Doğrulanamadı'}</td></tr>)}</tbody></table>{!addons.length&&<p className="py-6 text-center text-xs text-slate-500">Henüz bütünlük taraması yapılmadı.</p>}</div></Card></div><Card title="Karantina" subtitle="Bozuk JAR, yasaklı çalıştırılabilir dosya veya ClamAV bulgusu yeni yüklemede doğrudan kurulmaz." icon={ShieldAlert}><div className="overflow-x-auto"><table className="w-full min-w-[840px] text-xs"><thead className="text-left text-slate-500"><tr><th className="pb-2">Asıl hedef</th><th>Neden</th><th>SHA-256</th><th>Boyut</th><th>Zaman</th><th>İşlem</th></tr></thead><tbody>{data.quarantine.map(q=><tr key={q.token} className="border-t border-emerald-950/45"><td className="py-2">{q.originalPath}</td><td>{q.reason}</td><td className="font-mono text-slate-500">{q.sha256?.slice(0,12)}…</td><td>{formatBytes(q.size)}</td><td>{timeAgo(q.createdAt)}</td><td><div className="flex gap-1"><Button size="sm" variant="outline" className="h-6 text-xs" disabled={!!busy} onClick={async()=>{if(await actionConfirm.ask('Bu dosya güvenlik uyarısına rağmen geri yüklenecek. Mevcut hedef varsa önce yedeklenir.',{title:'Karantinadan geri yükle',confirmLabel:'Geri yükle',danger:true,requiredText:'GERİ YÜKLE'}))await act('quarantine-restore',{token:q.token})}}>Geri yükle</Button><Button size="sm" variant="destructive" className="h-6 text-xs" disabled={!!busy} onClick={async()=>{if(await actionConfirm.ask('Karantinadaki dosya kalıcı olarak silinecek.',{title:'Karantina dosyasını sil',confirmLabel:'Kalıcı sil',danger:true,requiredText:'SİL'}))await act('quarantine-delete',{token:q.token})}}>Sil</Button></div></td></tr>)}</tbody></table>{!data.quarantine.length&&<p className="py-5 text-center text-xs text-slate-600">Karantinada dosya yok.</p>}</div><p className="mt-2 text-xs text-slate-600">Geri yükleme backend tarafından sunucu çalışıyorsa reddedilir.</p></Card></div>}
function EventsFull({events,query,setQuery}:{events:SecurityEvent[];query:string;setQuery:(v:string)=>void}){return <EventsTable events={events} query={query} setQuery={setQuery} onAll={()=>{}}/>}
function PoliciesTab({data,busy,act}:{data:SecurityData;busy:string;act:(a:string,p?:Record<string,unknown>)=>Promise<any>}){const actionConfirm=useActionConfirm();return <>{actionConfirm.dialog}<div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.policies.profiles.map(id=><Card key={id} title={policyLabels[id]||id} subtitle={policyDescription(id)} icon={ShieldCheck} action={data.policies.active===id?<span className="rounded bg-emerald-500/10 px-2 py-1 text-xs text-emerald-300">Aktif</span>:undefined}><div className="space-y-1 text-xs text-slate-400">{policyFeatures(id).map(x=><div key={x} className="flex gap-2"><CheckCircle2 className="mt-0.5 size-3 shrink-0 text-emerald-300"/>{x}</div>)}</div><div className="mt-3 flex gap-2"><Button size="sm" variant="outline" className="h-7 flex-1 text-xs" disabled={!!busy} onClick={async()=>{const d=await act('policy-preview',{profile:id});if(d?.preview)alert(d.preview.join('\n'))}}>Önizle</Button><Button size="sm" className="h-7 flex-1 bg-emerald-600 text-xs text-emerald-950" disabled={!!busy} onClick={async()=>{const preview=await act('policy-preview',{profile:id});if(!preview?.preview)return;const ok=await actionConfirm.ask(`${policyLabels[id]||id} politikası şu değişiklikleri uygulayacak:\n\n${preview.preview.join('\n')}`,{title:'Güvenlik politikasını uygula',confirmLabel:'Politikayı uygula',danger:id==='strict'||id==='cracked',requiredText:'UYGULA'});if(ok)await act('policy-apply',{profile:id,confirmed:true})}}>Uygula</Button></div></Card>)}</div></>}function policyDescription(id:string){return id==='strict'?'Maksimum koruma; public saldırı yüzeyini azaltır.':id==='public'?'Herkese açık SMP için dengeli ağ ve oyuncu güvenliği.':id==='private'?'Whitelist ve sınırlı erişim odaklı özel sunucu profili.':id==='cracked'?'Offline-mode için ek auth ve rate-limit odaklı profil.':id==='custom'?'Tüm modülleri tek tek özelleştirin.':'Güvenli varsayılanlar ve düşük sürtünme.'}
function policyFeatures(id:string){if(id==='strict')return ['Premium doğrulama açılır','Whitelist açılır','RCON kapatılır','TCP rate-limit açılır'];if(id==='public')return ['RCON kapatılır','TCP rate-limit açılır','Whitelist zorlanmaz'];if(id==='private')return ['Premium doğrulama açılır','Whitelist açılır','RCON kapatılır'];if(id==='cracked')return ['Premium doğrulama kapatılır','RCON kapatılır','TCP rate-limit açılır','Ek auth ayrıca gerekir'];if(id==='custom')return ['Otomatik güvenlik değişikliği uygulanmaz'];return ['RCON koruması açık tutulur']}
function HistoryTab({data}:{data:SecurityData}){const max=Math.max(1,...data.history.flatMap(x=>[x.failed,x.blocked,x.anticheat,x.files]));return <div className="space-y-3"><div className="grid gap-3 sm:grid-cols-3"><SummaryCard icon={Clock3} title="Son 24 saat" value={String(data.historyWindows.d1)} detail="DB güvenlik olayı" onClick={()=>{}} tone="good"/><SummaryCard icon={History} title="Son 7 gün" value={String(data.historyWindows.d7)} detail="DB güvenlik olayı" onClick={()=>{}} tone="good"/><SummaryCard icon={Database} title="Son 30 gün" value={String(data.historyWindows.d30)} detail="DB güvenlik olayı" onClick={()=>{}} tone="good"/></div><Card title="Güvenlik geçmişi" subtitle="Başarısız giriş, engellenen IP ve anti-cheat/dosya olayları gerçek DB kayıtlarından üretilir." icon={History}><div className="mb-2 flex gap-4 text-xs text-slate-500"><span>1. bar: başarısız</span><span>2. bar: engellenen</span><span>3. bar: anti-cheat + dosya</span></div><div className="grid gap-2">{data.history.length?data.history.map(d=><div key={d.day} className="grid grid-cols-[88px_1fr_34px_1fr_34px_1fr_34px] items-center gap-2 text-xs"><span className="text-slate-500">{d.day}</span><MiniBar value={d.failed} max={max}/><span>{d.failed}</span><MiniBar value={d.blocked} max={max}/><span>{d.blocked}</span><MiniBar value={d.anticheat+d.files} max={max}/><span>{d.anticheat+d.files}</span></div>):<p className="py-10 text-center text-xs text-slate-500">Henüz yeterli veri yok.</p>}</div></Card></div>}
function ScoreBreakdownCard({items}:{items:ScoreBreakdown[]}){return <Card title="Güvenlik puanı hesap dökümü" subtitle="Puanın hangi gerçek kontrolden ne kadar etkilendiğini gösterir." icon={Gauge}>{items.length?items.map(i=><div key={i.key} className="flex items-start gap-2 border-b border-emerald-950/40 py-1.5 last:border-0"><span className={`mt-1 size-2 shrink-0 rounded-full ${i.status==='good'?'bg-emerald-400':i.status==='bad'?'bg-red-400':i.status==='warn'?'bg-amber-400':'bg-slate-500'}`}/><div className="min-w-0 flex-1"><div className="flex justify-between gap-2 text-xs"><b className="text-slate-200">{i.label}</b><span className={i.penalty?'text-amber-300':'text-emerald-300'}>{i.penalty?`-${i.penalty}`:'0'}</span></div><p className="truncate text-xs text-slate-600">{i.detail}</p></div></div>):<p className="py-5 text-center text-xs text-slate-600">Puan için tam güvenlik taraması gerekli.</p>}</Card>}
function IntegrationRow({label,status}:{label:string;status:string}){const active=status==='active'||status==='supported';return <div className="flex items-center justify-between border-b border-emerald-950/40 py-1.5 text-xs last:border-0"><span>{label}</span><span className={active?'text-emerald-300':status==='error'?'text-red-300':'text-amber-300'}>{active?'Aktif':status==='off'?'Kapalı':status==='error'?'Hata':'Entegrasyon gerekli'}</span></div>}
function AutomationLine({label,row,busy,onToggle}:{label:string;row:AutomationRow|null;busy:string;onToggle:(enabled:boolean)=>void}){const active=Boolean(row?.enabled);const schedule=!row?'Henüz oluşturulmadı':row.cadence==='interval'?`Her ${row.intervalMinutes||'—'} dk`:row.timeOfDay?`Her gün ${row.timeOfDay}`:'Günlük';return <div className="flex items-center gap-2 border-b border-emerald-950/40 py-1.5 text-xs last:border-0"><div className="min-w-0 flex-1"><div className="text-slate-300">{label}</div><div className="text-xs text-slate-600">{schedule}{row?.lastRunAt?` · Son: ${timeAgo(row.lastRunAt)}`:''}</div></div><button disabled={!!busy} onClick={()=>onToggle(!active)} className={`rounded px-2 py-1 text-xs ${active?'border border-red-500/30 text-red-300':'bg-emerald-600 text-emerald-950'} disabled:opacity-40`}>{active?'Kapat':'Etkinleştir'}</button></div>}
function formatBytes(value:number){if(!Number.isFinite(value)||value<=0)return '0 B';if(value<1024)return `${value} B`;if(value<1024*1024)return `${(value/1024).toFixed(1)} KB`;if(value<1024*1024*1024)return `${(value/1024/1024).toFixed(1)} MB`;return `${(value/1024/1024/1024).toFixed(2)} GB`}
function MiniBar({value,max}:{value:number;max:number}){return <div className="h-2 rounded bg-slate-800"><div className="h-full rounded bg-emerald-400" style={{width:`${Math.round(value/max*100)}%`}}/></div>}
function Select({label,value,options,onChange,disabled}:{label:string;value:string;options:Array<[string,string]>;onChange:(v:string)=>void;disabled?:boolean}){return <label className="text-xs text-slate-500">{label}<select value={value} disabled={disabled} onChange={e=>onChange(e.target.value)} className="mt-1 h-8 w-full rounded-md border border-emerald-950/70 bg-[#07130f] px-2 text-xs text-white disabled:opacity-50">{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}
function NumberField({label,value,onChange,disabled}:{label:string;value:number;onChange:(v:number)=>void;disabled?:boolean}){return <label className="text-xs text-slate-500">{label}<Input type="number" value={String(value)} disabled={disabled} onChange={e=>onChange(Number(e.target.value)||0)} className="mt-1 h-8 border-emerald-950/70 bg-[#07130f] text-xs"/></label>}
function Notice({tone,title,text}:{tone:'info'|'warn'|'danger';title:string;text:string}){const c=tone==='danger'?'border-red-500/25 bg-red-950/15 text-red-200':tone==='warn'?'border-amber-500/25 bg-amber-950/15 text-amber-100':'border-blue-500/25 bg-blue-950/15 text-blue-100';return <div className={`rounded-lg border p-3 ${c}`}><div className="flex gap-2"><AlertTriangle className="mt-0.5 size-4 shrink-0"/><div><p className="text-xs font-semibold">{title}</p><p className="mt-1 text-xs leading-4 opacity-80">{text}</p></div></div></div>}
function timeAgo(value:string){const ms=new Date(value).getTime()-Date.now();const abs=Math.abs(ms);const future=ms>0;const min=Math.round(abs/60000);const h=Math.round(abs/3600000);const d=Math.round(abs/86400000);const text=min<60?`${Math.max(1,min)} dk`:h<24?`${Math.max(1,h)} saat`:`${Math.max(1,d)} gün`;return future?`${text} sonra`:`${text} önce`}
